protocol Coordinator: AnyObject { func start() }

final class CheckoutCoordinator: Coordinator {
    private let nav: UINavigationController
    private let factory: ScreenFactory
    var onFinish: (() -> Void)?

    init(nav: UINavigationController, factory: ScreenFactory) {
        self.nav = nav; self.factory = factory
    }

    func start() {
        let cart = factory.makeCart()
        cart.onCheckout = { [weak self] in self?.showPayment() }
        nav.pushViewController(cart, animated: true)
    }
    private func showPayment() {
        let payment = factory.makePayment()
        payment.onPaid = { [weak self] in self?.onFinish?() }
        nav.pushViewController(payment, animated: true)
    }
}
